// Every Dart program starts running in main().
void main() {
  // print() writes a line of text and moves to the next one.
  print('Hello, world!');
  print('Welcome to Dart.');

  // Single or double quotes: both make a string.
  print("It's easy to start.");

  // print() also writes numbers and the result of a sum.
  print(42);
  print(7 * 6);
  print(2 + 3);

  // An empty string leaves a blank line.
  print('');

  // Every instruction ends with a semicolon.
  print('Dart is the language of Flutter apps.');
  print('Bye!');
}

void main() {
  // The type goes before the name: String, int, double, bool.
  String city = 'Valencia';
  int population = 800000;
  double temperature = 22.5;
  bool byTheSea = true;

  // $name puts a variable inside the text.
  print('$city has $population people');
  print('Today: $temperature degrees. By the sea? $byTheSea');

  // var lets Dart work out the type from the first value.
  var visitors = 1200;
  visitors = visitors + 300;
  print('Visitors: $visitors');
  // visitors = 'many';  // Error: visitors is an int.

  // final: given a value once, it can never change.
  final mayor = 'Elena Ruiz';
  // const: a fixed value, known before the program runs.
  const speedLimit = 50;
  // speedLimit = 60;  // Error: a const cannot change.
  print('Mayor: $mayor. Speed limit: $speedLimit km/h');

  // runtimeType tells the type of a value.
  print(city.runtimeType);
  print(visitors.runtimeType);
  print(temperature.runtimeType);
  print(byTheSea.runtimeType);
}

void main() {
  int eggs = 34;
  int perBox = 6;

  // ${...} puts the result of an expression in the text.
  print('34 + 10 = ${eggs + 10}');
  print('34 * 2 = ${eggs * 2}');

  // / always gives a double, even with two ints.
  print('34 / 6 = ${eggs / perBox}');

  // ~/ keeps only the whole part; % gives the remainder.
  int boxes = eggs ~/ perBox;
  int left = eggs % perBox;
  print('$boxes full boxes and $left eggs left over');

  // The same idea turns minutes into hours and minutes.
  int minutes = 135;
  print('$minutes min = ${minutes ~/ 60} h ${minutes % 60} min');

  // * goes before +; brackets change the order.
  print('2 + 3 * 4 = ${2 + 3 * 4}, (2 + 3) * 4 = ${(2 + 3) * 4}');

  // Doubles and their rounding methods.
  double total = 3.75 * 3;
  print('Total: $total = ${total.toStringAsFixed(2)} euros');
  print('round: ${total.round()}, floor: ${total.floor()}, ceil: ${total.ceil()}');

  // += and ++ update a variable.
  int score = 10;
  score += 5;
  score++;
  print('Score: $score');
}

void main() {
  String name = 'Lucia';
  String city = "Seville";

  // + joins strings; $name puts a variable inside the text.
  print('Hello, ' + name + '!');
  print('Hello, $name from $city!');

  // ${...} takes any expression, not only a name.
  int age = 29;
  print('Next year $name will be ${age + 1}.');
  print('$name has ${name.length} letters.');
  print('Shouting: ${city.toUpperCase()}');

  // [index] gives one character; the first one is at 0.
  print('First letter: ${name[0]}, last: ${name[name.length - 1]}');

  // A backslash writes quotes and dollars as they are.
  print('It\'s \$12 for the ticket.');
  print("She said: \"See you in $city\"");

  // Three quotes allow text on several lines.
  String ticket = '''
Passenger: $name
Age: $age
To: $city''';
  print(ticket);

  // * repeats a string.
  print('=' * 20);
}

import 'dart:io';

void main() {
  // stdout.write prints without a new line, like a question.
  stdout.write('What is your name? ');
  // readLineSync() reads one line of text (or null if there is none).
  String name = stdin.readLineSync() ?? '';
  print('Hello, $name!');

  // What is typed is always text: int.parse turns it into a number.
  stdout.write('How old are you? ');
  int age = int.parse(stdin.readLineSync() ?? '0');
  print('In ten years you will be ${age + 10}.');

  // double.parse for numbers with decimals.
  stdout.write('Price of a coffee? ');
  double price = double.parse(stdin.readLineSync() ?? '0');
  stdout.write('Coffees a week? ');
  int cups = int.parse(stdin.readLineSync() ?? '0');

  double perYear = price * cups * 52;
  print('$name, you spend ${perYear.toStringAsFixed(2)} euros a year on coffee.');

  // tryParse gives null instead of failing on bad text.
  stdout.write('Favourite number? ');
  int? favourite = int.tryParse(stdin.readLineSync() ?? '');
  print(favourite == null ? 'That is not a number.' : 'Doubled: ${favourite * 2}');
}

void main() {
  int temperature = 31;

  // if runs its block only when the condition is true.
  if (temperature > 30) {
    print('It is $temperature degrees: drink water.');
  }

  // else if and else choose one path out of several.
  int score = 72;
  String grade;
  if (score >= 90) {
    grade = 'A';
  } else if (score >= 70) {
    grade = 'B';
  } else if (score >= 50) {
    grade = 'C';
  } else {
    grade = 'F';
  }
  print('Score $score: grade $grade');

  // && (and), || (or) and ! (not) combine conditions.
  int age = 16;
  bool withParent = true;
  bool isWeekend = false;
  if (age >= 18 || withParent) print('You can see the film.');
  if (!isWeekend && temperature > 25) print('A hot working day.');
  print('Is it a B? ${grade == 'B'}');

  // condition ? valueIfTrue : valueIfFalse
  String ticket = age < 18 ? 'junior' : 'adult';
  print('Ticket: $ticket, result: ${score >= 50 ? 'pass' : 'fail'}');
}

void main() {
  String day = 'Sat'; // switch runs the case that matches
  switch (day) {
    case 'Sat' || 'Sun':
      print('$day: weekend, the shop opens at 10.');
    default:
      print('$day: open from 9 to 8.');
  }

  // switch expression: gives back a value. _ catches the rest.
  int month = 4;
  String season = switch (month) {
    12 || 1 || 2 => 'winter',
    3 || 4 || 5 => 'spring',
    6 || 7 || 8 => 'summer',
    _ => 'autumn',
  };
  print('Month $month is in $season.');

  // Patterns can also compare: >= 90, >= 70...
  int score = 84;
  String grade = switch (score) { >= 90 => 'A', >= 70 => 'B', >= 50 => 'C', _ => 'F' };
  print('Score $score: grade $grade');

  // && joins two patterns; "when" adds an extra condition.
  int speed = 65;
  bool school = true;
  String note = switch (speed) {
    >= 0 && <= 50 => 'within the limit',
    _ when school => 'too fast near a school',
    _ => 'slow down',
  };
  print('$speed km/h: $note');
}

void main() {
  // for: a start, a condition and a step.
  for (int i = 1; i <= 5; i++) {
    print('7 x $i = ${7 * i}');
  }

  // while repeats as long as the condition is true.
  double savings = 100;
  int years = 0;
  while (savings < 150) {
    savings *= 1.10; // 10% interest each year
    years++;
  }
  print('$years years to reach ${savings.toStringAsFixed(2)} euros');

  // do-while checks at the end, so it runs at least once.
  int countdown = 3;
  do {
    print('Countdown: $countdown');
    countdown--;
  } while (countdown > 0);

  // continue jumps to the next turn; break leaves the loop.
  String odds = '';
  for (int n = 1; n <= 20; n++) {
    if (n % 2 == 0) continue;
    if (n > 11) break;
    odds += '$n ';
  }
  print('Odd numbers up to 11: $odds');
}

void main() {
  // A list keeps values in order, between [ ].
  List<String> planets = ['Mercury', 'Venus', 'Earth', 'Mars'];
  print(planets);
  print('The list has ${planets.length} planets');

  // Positions start at 0, so the last one is length - 1.
  print('First: ${planets[0]}, last: ${planets[planets.length - 1]}');
  print('Also: ${planets.first} and ${planets.last}');

  // A position can be given a new value.
  planets[3] = 'Mars (the red one)';

  // for-in goes through every element.
  for (var planet in planets) {
    print('- $planet');
  }

  // var works out the type: here, List<int>.
  var moons = [0, 0, 1, 2];
  int total = 0;
  for (int i = 0; i < moons.length; i++) {
    total += moons[i];
  }
  print('Moons in total: $total');

  // contains, indexOf and isEmpty answer questions.
  print('Has Venus? ${planets.contains('Venus')}');
  print('Earth is at position ${planets.indexOf('Earth')}');
  print('Pluto is at ${planets.indexOf('Pluto')}. Empty? ${planets.isEmpty}');
}

void main() {
  var queue = ['Ana', 'Ben', 'Carla'];

  // add puts one element at the end; addAll puts several.
  queue.add('Dani');
  queue.addAll(['Eva', 'Fran']);
  print('Queue: $queue');

  // insert puts it at a given position.
  queue.insert(0, 'Zoe');
  print('Zoe goes first: $queue');

  // remove by value, removeAt by position, removeLast the last one.
  queue.remove('Ben');
  String served = queue.removeAt(0);
  queue.removeLast();
  print('$served served, Ben left, Fran gave up: $queue');

  // sort orders the list itself, from lowest to highest.
  var scores = [72, 95, 58, 81, 64, 88];
  scores.sort();
  print('Sorted: $scores');

  // reversed gives the elements backwards; toList makes a list.
  var ranking = scores.reversed.toList();
  print('Ranking: $ranking');

  // sublist(start, end) copies a part; end is not included.
  print('Top 3: ${ranking.sublist(0, 3)}');
  print('From the 4th on: ${ranking.sublist(3)}');

  queue.clear(); // clear empties the list
  print('Queue after closing: $queue (${queue.length})');
}

void main() {
  // A set keeps each value only once, between { }.
  var tags = {'dart', 'flutter', 'mobile'};
  tags.add('dart'); // already there: nothing changes
  tags.add('desktop');
  print('Tags: $tags (${tags.length})');

  // toSet() removes the repeated values of a list.
  var visits = ['Rome', 'Paris', 'Rome', 'Lisbon', 'Paris', 'Rome'];
  var cities = visits.toSet();
  print('${visits.length} visits, ${cities.length} cities: $cities');

  // contains is very quick in a set, even a big one.
  print('Been to Lisbon? ${cities.contains('Lisbon')}');

  // Operations between two sets.
  var ana = {'chess', 'tennis', 'piano', 'cooking'};
  var ben = {'tennis', 'football', 'cooking'};
  print('Both like: ${ana.intersection(ben)}');
  print('Either likes: ${ana.union(ben)}');
  print('Only Ana: ${ana.difference(ben)}');

  // remove takes a value out.
  ana.remove('piano');
  print('Ana now: $ana');

  // {} alone is an empty map: an empty set needs its type.
  var empty = <String>{};
  print('Empty set: $empty, is empty? ${empty.isEmpty}');
}

